/**
 * Server-only: the listed index futures (Nifty, Bank Nifty, Sensex), from Upstox's public instrument files (no
 * token needed).
 *
 * `/v2/option/contract` (contracts.ts) lists options only, so a futures position's bare `NSE_FO|58875` matches
 * nothing there. The instrument file knows it - and it is also the only place that turns "the Nifty December
 * future" into the instrument key a quote is asked under, which the Live Portfolio price poll needs.
 *
 * The NSE file is ~44 MB once unzipped (every equity and F&O contract) and the BSE one ~11 MB, regenerated by
 * Upstox every morning. Each is fetched at most once per IST day, and only when a futures position is actually
 * held, so a book of options never pays for it. Only the futures of the three indices are kept.
 */

import { gunzipSync } from "node:zlib";

import { istDateString } from "@/lib/calculateStrategy";
import { round2 } from "@/lib/calculateTrade";
import { INDEX_INSTRUMENTS, type IndexInstrument } from "@/lib/types";
import type { UpstoxGetError } from "@/lib/upstox/api";
import type { PositionContract } from "@/lib/upstox/contracts";
import type { UpstoxFutureQuoteSuccess } from "@/lib/upstox/types";
import { parseQuoteEntry } from "@/lib/upstox/watchQuotes";

const IST_OFFSET_MS = 5.5 * 3_600_000;

export type FuturesExchange = "NSE" | "BSE";

const SOURCES: Record<FuturesExchange, { url: string; segment: string }> = {
  NSE: { url: "https://assets.upstox.com/market-quote/instruments/exchange/NSE.json.gz", segment: "NSE_FO" },
  BSE: { url: "https://assets.upstox.com/market-quote/instruments/exchange/BSE.json.gz", segment: "BSE_FO" },
};

/** The exchange an index's futures trade on. */
export function futuresExchangeFor(instrument: IndexInstrument): FuturesExchange {
  return instrument === "SENSEX" ? "BSE" : "NSE";
}

/** The exchange a futures position's instrument token belongs to - null for anything that isn't an NSE / BSE F&O key. */
export function futuresExchangeOfKey(key: string): FuturesExchange | null {
  return key.startsWith("NSE_FO|") ? "NSE" : key.startsWith("BSE_FO|") ? "BSE" : null;
}

export type IndexFutures = {
  /** Every live index future by Upstox instrument_key - strike and optionType are null. */
  contracts: Map<string, PositionContract>;
  /** The key to quote a future under, as `${instrument}|${yyyy-mm-dd}` (see futureContractId). */
  keyByContract: Map<string, string>;
};

export function futureContractId(instrument: IndexInstrument, expiry: string): string {
  return `${instrument}|${expiry}`;
}

function isIndex(value: unknown): value is IndexInstrument {
  return typeof value === "string" && (INDEX_INSTRUMENTS as readonly string[]).includes(value);
}

/** The file gives `expiry` as epoch milliseconds (23:59 IST on the expiry day). */
function toIsoDate(value: unknown): string | null {
  if (typeof value === "number" && Number.isFinite(value)) return new Date(value + IST_OFFSET_MS).toISOString().slice(0, 10);
  if (typeof value === "string" && /^\d{4}-\d{2}-\d{2}/.test(value)) return value.slice(0, 10);
  return null;
}

/**
 * Reduces one exchange's raw instrument rows to the futures of the three indices that haven't expired yet
 * (`todayIso`, IST - a contract is still live through its expiry day). Exported for testing.
 */
export function parseIndexFutures(rows: unknown, segment: string, todayIso: string = istDateString(Date.now())): IndexFutures | null {
  if (!Array.isArray(rows)) return null;
  const contracts = new Map<string, PositionContract>();
  const keyByContract = new Map<string, string>();

  for (const row of rows as Record<string, unknown>[]) {
    // Matches the index itself only: MIDCPNIFTY, FINNIFTY and NIFTYNXT50 have their own underlying symbols.
    if (row.segment !== segment || row.instrument_type !== "FUT" || !isIndex(row.underlying_symbol)) continue;
    const key = row.instrument_key;
    const expiry = toIsoDate(row.expiry);
    const lotSize = typeof row.lot_size === "number" ? row.lot_size : Number(row.lot_size);
    if (typeof key !== "string" || !expiry || expiry < todayIso || !(lotSize > 0)) continue;

    contracts.set(key, { instrument: row.underlying_symbol, strike: null, optionType: null, expiry, lotSize });
    keyByContract.set(futureContractId(row.underlying_symbol, expiry), key);
  }
  return { contracts, keyByContract };
}

/**
 * One entry of Upstox's `/v2/market-quote/quotes` for a future, reduced to what Live Portfolio shows. The price
 * and previous close are read the way the Watchlist reads them (the close is the price less `net_change` - for the
 * Dec Nifty future 25,601.2 less 151.6 is the 25,449.6 its position reports as `close_price`). Null when nothing
 * has traded, so a row of zeros never passes for a price.
 */
export function parseFutureQuote(entry: unknown, instrumentKey: string): UpstoxFutureQuoteSuccess | null {
  const quote = parseQuoteEntry(entry, null);
  if (!quote) return null;
  const oi = (entry as { oi?: unknown }).oi;
  return {
    instrumentKey,
    ltp: quote.price,
    // The close is worked out as price less net change, which leaves float noise (25449.600000000002) - a close is paise.
    prevClose: quote.prevClose === null ? null : round2(quote.prevClose),
    oi: typeof oi === "number" && Number.isFinite(oi) && oi > 0 ? oi : null,
    volume: quote.volume,
  };
}

type FuturesResult = IndexFutures | UpstoxGetError;

function isFuturesError(result: FuturesResult): result is UpstoxGetError {
  return "error" in result;
}

async function fetchExchangeFutures(exchange: FuturesExchange): Promise<FuturesResult> {
  const { url, segment } = SOURCES[exchange];
  let response: Response;
  try {
    response = await fetch(url, { cache: "no-store" });
  } catch {
    return { error: `Couldn't reach Upstox's ${exchange} contract list.`, status: 502 };
  }
  if (!response.ok) return { error: `Upstox's ${exchange} contract list returned ${response.status}`, status: 502 };

  let rows: unknown;
  try {
    rows = JSON.parse(gunzipSync(Buffer.from(await response.arrayBuffer())).toString("utf8"));
  } catch {
    return { error: `Upstox's ${exchange} contract list couldn't be read.`, status: 502 };
  }
  const parsed = parseIndexFutures(rows, segment);
  if (!parsed || parsed.contracts.size === 0) return { error: `Upstox's ${exchange} contract list was missing the expected data.`, status: 502 };
  return parsed;
}

const cache: Partial<Record<FuturesExchange, { day: string; data: IndexFutures }>> = {};
// Several polls can land together on a cold start - they share the one download per exchange.
const inflight: Partial<Record<FuturesExchange, Promise<FuturesResult>>> = {};

/** Cached for the IST day: contracts are listed before a session, not during one. Only a complete result is kept. */
function getExchangeFutures(exchange: FuturesExchange): Promise<FuturesResult> {
  const today = istDateString(Date.now());
  const cached = cache[exchange];
  if (cached?.day === today) return Promise.resolve(cached.data);
  const pending = inflight[exchange];
  if (pending) return pending;

  const request = fetchExchangeFutures(exchange)
    .then((result) => {
      if (!isFuturesError(result)) cache[exchange] = { day: today, data: result };
      return result;
    })
    .finally(() => {
      delete inflight[exchange];
    });
  inflight[exchange] = request;
  return request;
}

/** The futures of the given exchanges, merged. All or nothing: a partial map would quietly drop that exchange's positions. */
export async function getIndexFutures(exchanges: Iterable<FuturesExchange>): Promise<IndexFutures | UpstoxGetError> {
  const results = await Promise.all([...new Set(exchanges)].map(getExchangeFutures));
  const merged: IndexFutures = { contracts: new Map(), keyByContract: new Map() };
  for (const result of results) {
    if (isFuturesError(result)) return result;
    for (const [key, contract] of result.contracts) merged.contracts.set(key, contract);
    for (const [id, key] of result.keyByContract) merged.keyByContract.set(id, key);
  }
  return merged;
}
